package vn.smartfarm.iot.telemetry;
import com.fasterxml.jackson.databind.*;import com.fasterxml.jackson.databind.node.ObjectNode;
import java.time.*;import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;import org.springframework.beans.factory.ObjectProvider;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.test.context.bean.override.mockito.MockitoBean;import org.springframework.transaction.PlatformTransactionManager;import org.springframework.web.server.ResponseStatusException;
import vn.smartfarm.iot.control.*;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@SpringBootTest(properties={"spring.datasource.url=${SMARTFARM_TEST_DB_URL}","spring.flyway.schemas=telemetry_test","spring.flyway.default-schema=telemetry_test","smartfarm.mqtt.enabled=false","smartfarm.control.enabled=true","smartfarm.control.pump-fencing-enabled=true"})
@EnabledIfEnvironmentVariable(named="SMARTFARM_TEST_DB_URL",matches=".+")
class PumpFencingTest {
 @Autowired PumpService pump;@Autowired PumpCommandFencing fencing;@Autowired JdbcTemplate jdbc;@Autowired ObjectMapper mapper;@Autowired PlatformTransactionManager manager;@Autowired ObjectProvider<CommandTransport> providers;@MockitoBean CommandTransport transport;
 final UUID boot=UUID.fromString("71000000-0000-4000-8000-000000000001");long seq,queue;
 @BeforeEach void setup()throws Exception{jdbc.execute("TRUNCATE pump_command,pump_status,pump_state_history,watering_run,watering_rule");jdbc.update("INSERT INTO watering_rule(singleton) VALUES(1)");seq=0;queue=jdbc.queryForObject("SELECT COUNT(*) FROM irrigation_queue_request",Long.class);reset(transport);when(transport.controlConnected()).thenReturn(true);report(boot,0,"OFF",false,false);}
 @AfterEach void noQueueDispatch(){assertEquals(queue,jdbc.queryForObject("SELECT COUNT(*) FROM irrigation_queue_request",Long.class));}
 ObjectNode packet(UUID b,String state,boolean locked){return mapper.createObjectNode().put("schemaVersion",1).put("deviceId","PUMP01").put("bootId",b.toString()).put("sequence",++seq).put("timestamp",Instant.now().toString()).put("reportedState",state).put("safetyLockout",locked);}
 void report(UUID b,long ordinal,String state,boolean locked,boolean restart)throws Exception{var p=packet(b,state,locked).put("connection","ONLINE");p.putObject("commandFence").put("version",1).put("lastOrdinal",ordinal).put("restartRequired",restart);receive("status",p);}
 void receive(String leaf,JsonNode p)throws Exception{pump.receive("smartfarm/FARM001/PUMP01/"+leaf,mapper.writeValueAsBytes(p));}
 long rank(UUID id){return jdbc.queryForObject("SELECT fence_ordinal FROM pump_command WHERE command_id=?",Long.class,id);}
 PumpService.Command command(String action){return pump.create(new PumpService.Request(action,action.equals("ON")?5:null));}
 ObjectNode ack(PumpService.Command c,UUID b,String state)throws Exception{var p=packet(b,state,false).put("commandId",c.commandId().toString()).put("stage","EXECUTED").put("status","SUCCESS").putNull("errorCode");p.putObject("commandFence").put("version",1).put("ordinal",rank(c.commandId()));return p;}
 String stored(UUID id){return jdbc.queryForObject("SELECT state FROM pump_command WHERE command_id=?",String.class,id);}
 @Test void persistedBeforeTransportAndWireBindsCurrentBoot()throws Exception{doAnswer(call->{var p=mapper.readTree((byte[])call.getArgument(0));UUID id=UUID.fromString(p.path("commandId").asText());assertEquals("PENDING",stored(id));assertEquals(boot.toString(),p.path("commandFence").path("targetBootId").asText());assertEquals(rank(id),p.path("commandFence").path("ordinal").asLong());return null;}).when(transport).publishCommand(any());assertEquals("SENT",command("ON").state());assertTrue(pump.status().commandFence().required());assertTrue(pump.status().commandFence().compatible());}
 @Test void pendingOnBlocksAnotherButOffGetsHigherOrdinal(){var a=command("ON");assertThrows(ResponseStatusException.class,()->command("ON"));var b=command("OFF");assertTrue(rank(b.commandId())>rank(a.commandId()));}
 @Test void timeoutOutsideTwentyDoesNotReleaseUnseenOrdinal()throws Exception{var first=command("ON");for(int i=0;i<22;i++)command("OFF");jdbc.update("UPDATE pump_command SET state='TIMED_OUT'");assertEquals(20,pump.commands().size());assertThrows(ResponseStatusException.class,()->command("ON"));long high=jdbc.queryForObject("SELECT MAX(fence_ordinal) FROM pump_command",Long.class);report(boot,high,"OFF",false,false);assertEquals("SENT",command("ON").state());assertTrue(rank(first.commandId())<high);}
 @Test void wrongBootOrMissingFenceAckCannotCompleteOn()throws Exception{var c=command("ON");receive("ack",ack(c,UUID.randomUUID(),"ON"));assertEquals("SENT",stored(c.commandId()));var p=ack(c,boot,"ON");p.remove("commandFence");receive("ack",p);assertEquals("SENT",stored(c.commandId()));receive("ack",ack(c,boot,"ON"));assertEquals("EXECUTED",stored(c.commandId()));}
 @Test void wrongOrdinalAckCannotCompleteOn()throws Exception{var c=command("ON");var p=ack(c,boot,"ON");((ObjectNode)p.path("commandFence")).put("ordinal",rank(c.commandId())+1);receive("ack",p);assertEquals("SENT",stored(c.commandId()));}
 @Test void lateOnAckNeverOverwritesNewerOffStatus()throws Exception{var a=command("ON");var earlyAck=ack(a,boot,"ON");var off=command("OFF");receive("ack",ack(off,boot,"OFF"));report(boot,rank(off.commandId()),"OFF",false,false);receive("ack",earlyAck);assertEquals("OFF",pump.status().reportedState());assertEquals("SENT",command("ON").state());}
 @Test void sameBootCannotDowngradeFenceOrRegressOrdinal()throws Exception{var off=command("OFF");report(boot,rank(off.commandId()),"OFF",false,false);var p=packet(boot,"ON",false).put("connection","ONLINE");receive("status",p);assertEquals("OFF",pump.status().reportedState());assertThrows(IllegalArgumentException.class,()->report(boot,0,"ON",false,false));report(boot,0,"OFF",false,false);assertEquals("OFF",pump.status().reportedState());assertEquals(rank(off.commandId()),pump.status().commandFence().lastOrdinal());}
 @Test void newBootStartsAtZeroButOldOnAckCannotAuthorizeIt()throws Exception{var c=command("ON");jdbc.update("UPDATE pump_command SET state='TIMED_OUT'");UUID next=UUID.randomUUID();report(next,0,"OFF",false,false);assertEquals(0L,pump.status().commandFence().lastOrdinal());assertEquals("SENT",command("ON").state());assertEquals(next,jdbc.queryForObject("SELECT target_boot_id FROM pump_command WHERE command_id<>? ORDER BY fence_ordinal DESC LIMIT 1",UUID.class,c.commandId()));}
 @Test void legacyDeviceBlocksOnResetButOffUsesLegacyEnvelope()throws Exception{UUID old=UUID.randomUUID();receive("status",packet(old,"OFF",false).put("connection","ONLINE"));assertFalse(pump.status().commandFence().compatible());assertThrows(ResponseStatusException.class,()->command("ON"));assertThrows(ResponseStatusException.class,()->command("RESET_LOCKOUT"));doAnswer(call->{assertFalse(mapper.readTree((byte[])call.getArgument(0)).has("commandFence"));return null;}).when(transport).publishCommand(any());assertEquals("SENT",command("OFF").state());}
 @Test void uncertainPublishNeverRetriesAndStillBlocksAfterTimeout()throws Exception{doThrow(new RuntimeException("unknown delivery")).when(transport).publishCommand(any());assertThrows(PumpService.UncertainPublish.class,()->command("ON"));jdbc.update("UPDATE pump_command SET state='TIMED_OUT'");assertThrows(ResponseStatusException.class,()->command("ON"));verify(transport,times(1)).publishCommand(any());}
 @Test void synchronousAckIsNotOverwrittenBySentAndCallbackPrecedesIt()throws Exception{var tracked=new java.util.concurrent.atomic.AtomicReference<UUID>();doAnswer(call->{assertNotNull(tracked.get());receive("ack",ack(new PumpService.Command(tracked.get(),"ON",5,Instant.now(),Instant.now(),"PENDING",null,null),boot,"ON"));return null;}).when(transport).publishCommand(any());assertEquals("EXECUTED",pump.create(new PumpService.Request("ON",5),tracked::set).state());}
 @Test void legacyEmergencyLatchRequiresRebootAndCannotClearWithinSameBoot()throws Exception{report(boot,0,"OFF",true,true);assertTrue(pump.status().commandFence().restartRequired());assertThrows(ResponseStatusException.class,()->command("RESET_LOCKOUT"));report(boot,0,"OFF",false,false);assertTrue(pump.status().commandFence().restartRequired());assertEquals("SENT",command("OFF").state());}
 @Test void unknownStatusOrdinalAndMalformedMetadataAreRejected()throws Exception{var p=packet(boot,"OFF",false).put("connection","ONLINE");p.putObject("commandFence").put("version",1).put("lastOrdinal",9007199254740991L).put("restartRequired",false);assertThrows(IllegalArgumentException.class,()->receive("status",p));((ObjectNode)p.path("commandFence")).put("lastOrdinal",0).remove("restartRequired");assertThrows(IllegalArgumentException.class,()->receive("status",p));}
 @Test void twoInstancesReserveOnlyOneOn()throws Exception{var other=new PumpCommandFencing(jdbc,mapper,providers,manager,true,true);var gate=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(2)){var a=pool.submit(()->{gate.await();try{return fencing.create(new PumpService.Request("ON",5),x->{}).state();}catch(ResponseStatusException e){return "BLOCKED";}});var b=pool.submit(()->{gate.await();try{return other.create(new PumpService.Request("ON",5),x->{}).state();}catch(ResponseStatusException e){return "BLOCKED";}});gate.countDown();var states=List.of(a.get(5,TimeUnit.SECONDS),b.get(5,TimeUnit.SECONDS));assertEquals(1,Collections.frequency(states,"SENT"));assertEquals(1,Collections.frequency(states,"BLOCKED"));}assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM pump_command",Integer.class));}
 @Test void disconnectedOffStillSavesStopIntent(){when(transport.controlConnected()).thenReturn(false);assertThrows(ResponseStatusException.class,()->command("OFF"));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM pump_command WHERE state='FAILED' AND error_code='MQTT_UNAVAILABLE'",Integer.class));}
 @Test void nativeInitialFenceStatusHasNoCommandOrQueueEffects()throws Exception{try(var in=getClass().getResourceAsStream("/pump-fence-status.json")){assertNotNull(in);var p=(ObjectNode)mapper.readTree(in);p.put("timestamp",Instant.now().toString()).put("sequence",++seq);receive("status",p);assertTrue(pump.status().commandFence().deviceEnabled());assertEquals(0L,pump.status().commandFence().lastOrdinal());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM pump_command",Integer.class));}}
 @Test void directDispatchStillRequiresControlFlag()throws Exception{var disabled=new PumpCommandFencing(jdbc,mapper,providers,manager,true,false);assertEquals(403,assertThrows(ResponseStatusException.class,()->disabled.create(new PumpService.Request("OFF",null),id->{})).getStatusCode().value());verify(transport,never()).publishCommand(any());}

}
